from fractions import Fraction as Q
Z=(Q(0),)*4;O=(Q(1),Q(0),Q(0),Q(0));S=(Q(0),Q(1),Q(0),Q(0));I=(Q(0),Q(0),Q(1),Q(0))
def a(x,y):return tuple(x[k]+y[k]for k in range(4))
def s(q,x):return tuple(q*z for z in x)
def n(x):return s(-1,x)
def cj(x):return(x[0],x[1],-x[2],-x[3])
def m(x,y):
 A,B,C,D=x;E,F,G,H=y
 return(A*E+3*B*F-C*G-3*D*H,A*F+B*E-C*H-D*G,A*G+3*B*H+C*E+3*D*F,A*H+B*G+C*F+D*E)
def sm(xs):
 z=Z
 for x in xs:z=a(z,x)
 return z
def mm(A,B):return[[sm(m(A[i][k],B[k][j])for k in range(len(B)))for j in range(len(B[0]))]for i in range(len(A))]
def dg(A):return[[cj(A[j][i])for j in range(len(A))]for i in range(len(A[0]))]
def kr(*xs):
 R=[[O]]
 for B in xs:R=[[m(R[i//len(B)][j//len(B[0])],B[i%len(B)][j%len(B[0])])for j in range(len(R[0])*len(B[0]))]for i in range(len(R)*len(B))]
 return R
def gram(M,q):assert mm(dg(M),M)==[[s(q,O),Z],[Z,s(q,O)]]
def edge(T,U,E):
 for i in range(2):
  for j in range(2):assert mm(dg(T[i]),U[j])==[[E[i][j],Z],[Z,E[i][j]]]
ID=[[O,Z],[Z,O]];EA=[[O],[Z],[Z],[O]];EB=[[Z],[O],[n(O)],[Z]];EC=[[O,Z],[Z,n(O)],[Z,n(O)],[n(O),Z]];JB=[[O,Z],[Z,n(O)]]
Wg=[[a(n(S),I),Z],[Z,s(-2,I)],[a(O,m(I,S)),Z],[Z,s(2,O)]];Wh=[[cj(x)for x in r]for r in Wg];ag=s(Q(1,2),a(n(S),n(I)));ah=cj(ag);Ug=[[m(ag,x)for x in r]for r in Wg];Uh=[[m(ah,x)for x in r]for r in Wh]
EY=[EA,EB];J=[ID,JB];EZ=[Ug,Uh];CY=[Uh,Ug]
T1=[mm(mm(kr(EC,ID,ID),kr(EY[k],ID)),J[k])for k in range(2)];T2=[mm(mm(kr(ID,EC,ID),kr(EY[k],ID)),J[k])for k in range(2)];T3=[mm(kr(EC,EZ[k]),CY[k])for k in range(2)];T4=[mm(mm(kr(ID,EC,ID),kr(ID,EZ[k])),CY[k])for k in range(2)];T5=[mm(mm(kr(ID,ID,EZ[k]),kr(ID,EZ[k])),CY[1-k])for k in range(2)]
for T,q in zip((T1,T2,T3,T4,T5),(4,4,128,128,512)):
 for X in T:gram(X,q)
D=[[O,Z],[Z,n(O)]];K=[[O,I],[O,n(I)]];P=[[Z,O],[O,Z]];E2=[[s(4,x)for x in r]for r in D];E42=[[s(16,x)for x in r]for r in K];E54=[[s(256,x)for x in r]for r in P];E35=[[s(256,x)for x in r]for r in ID];E31=E42
edge(T2,T1,E2);edge(T4,T2,E42);edge(T5,T4,E54);edge(T3,T5,E35);edge(T3,T1,E31)
assert K==mm(ID,mm(P,mm(K,D)))
print({'field':'Q(sqrt(3),i)','exact_path_grams':10,'exact_edge_blocks':5,'exact_pentagon':True,'status':'passed'})
